function validate([coordinates]) {
  if (!Array.isArray(coordinates) || coordinates.length < 2 || coordinates.length > 1000) return 'coordinates needs 2 to 1000 points.';
  const seen = new Set();
  for (const point of coordinates) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each coordinate is an integer from -10000 to 10000.';
    const id = point.join(',');
    if (seen.has(id)) return 'No point may appear twice.';
    seen.add(id);
  }
  return null;
}

