function checkStraightLine(coordinates) {
  // Reduce every offset from the first point to its primitive direction; all must agree up to sign.
  const gcd = (a, b) => (b === 0 ? Math.abs(a) : gcd(b, a % b));
  const key = ([x, y]) => {
    let a = x - coordinates[0][0];
    let b = y - coordinates[0][1];
    const g = gcd(Math.abs(a), Math.abs(b));
    a /= g;
    b /= g;
    if (a < 0 || (a === 0 && b < 0)) { a = -a; b = -b; }
    return a + ',' + b;
  };
  const directions = new Set(coordinates.slice(1).map(key));
  return directions.size === 1;
}

