function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 1000 : int(2, 8);
  const mode = rand();
  if (mode < 0.65) {
    // Points on one line, optionally with one point nudged off it.
    const reach = large ? 10 : 3;
    let a = 0;
    let b = 0;
    while (a === 0 && b === 0) { a = int(-reach, reach); b = int(-reach, reach); }
    const base = large ? [int(-1000, 1000), int(-1000, 1000)] : [int(-3, 3), int(-3, 3)];
    if (!large && rand() < 0.1) { base[0] = 10000 * Math.sign(a || 1) - a * 8; base[1] = Math.max(-10000, Math.min(10000, base[1])); }
    const span = large ? 900 : 8;
    const steps = Array.from({ length: 2 * span + 1 }, (_, i) => i - span);
    for (let i = steps.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [steps[i], steps[j]] = [steps[j], steps[i]];
    }
    const points = steps.slice(0, n).map(t => [base[0] + t * a, base[1] + t * b]);
    if (points.some(([x, y]) => Math.abs(x) > 10000 || Math.abs(y) > 10000)) return [steps.slice(0, n).map(t => [t * a, t * b])];
    if (rand() < 0.5) {
      const k = int(0, n - 1);
      const axis = a === 0 ? 0 : 1;
      points[k][axis] += points[k][axis] < 10000 ? 1 : -1;
    }
    return [points];
  }
  const range = large ? 10000 : 3;
  const seen = new Set();
  const points = [];
  while (points.length < n) {
    const point = [int(-range, range), int(-range, range)];
    const id = point.join(',');
    if (seen.has(id)) continue;
    seen.add(id);
    points.push(point);
  }
  return [points];
}
